def location(lang):
 content=head(lang,'location',t(lang,'Veien hit er starten<br>på noe roligere.','The way here is the start<br>of something quieter.'),t(lang,'Du finner Brennvik Panorama ved Vestfjorden i Hamarøy, med Tranøy og kystlandskapet like i nærheten.','Find Brennvik Panorama beside Vestfjorden in Hamarøy, close to Tranøy and the coastal landscape.'))
 content+=f'''<section class="section-small"><div class="wrap location-grid"><div>{eyebrow(t(lang,'Finn frem','Find us'))}<h2>Brennvik Panorama</h2><p>{t(lang,'Bruk hele adressen når du planlegger reisen. Kartlenkene åpner plasseringen i kartappen din.','Use the full address when planning your journey. The links open the location in your map app.')}</p><div class="address">Brennvikveien 37<br>8294 Hamarøy<br>{t(lang,'Norge','Norway')}</div><div class="map-actions"><a class="button" href="{esc(MAP)}" target="_blank" rel="noopener">Google Maps ↗</a><a class="button line" href="{esc(APPLE)}" target="_blank" rel="noopener">Apple Maps ↗</a></div></div><div class="map-panel">{pic(lang,'location',eager=True)}<div class="map-caption"><span>Hamarøy · Nordland</span><a href="{esc(MAP)}" target="_blank" rel="noopener">{t(lang,'Se på kart','View on map')} ↗</a></div></div></div></section>'''
 qas=faq(t(lang,'Den siste delen av kjøreturen','The last part of the drive'),t(lang,'Ta av hovedveien og inn på Brennvikveien. Hold lav fart, maksimalt 30 km/t på den siste strekningen. Ta til høyre ved krysset ved transformatorstasjonen og følg veien ned mot sjøen. Hytta ligger på høyre side.','Turn off the main road onto Brennvikveien. Drive slowly, at no more than 30 km/h on the final stretch. Turn right at the junction by the electrical transformer station and continue downhill towards the sea. The cabin is on your right.'))
 qas+=faq(t(lang,'Parkering','Parking'),t(lang,'Parker ved hytta, uten å blokkere veien eller tilkomsten for andre kjøretøy.','Park beside the cabin without blocking the road or access for other vehicles.'))
 qas+=faq(t(lang,'Planlegg reisen etter årstiden','Plan for the season'),t(lang,'Sjekk vær, føre og eventuelle ferger før avreise. Sett av tid til stopp underveis. På vinteren må bilen være utstyrt for vinterføre.','Check weather, road conditions and any ferry connections before you travel. Leave time for stops along the way. In winter, your car must be equipped for winter driving.'))
 content+=f'''<section class="section"><div class="wrap practical"><div>{eyebrow(t(lang,'Før ankomst','Before arrival'))}<h2 class="serif" style="font-size:42px;line-height:1.15">{t(lang,'Den siste biten<br>ned til havet.','The last stretch<br>down to the sea.')}</h2></div><div>{qas}</div></div></section>'''
 content+=f'''<section class="section-small" style="background:var(--paper2)"><div class="wrap practical"><div>{eyebrow(t(lang,'Spør oss','Get in touch'))}<h2 class="serif" style="font-size:42px;line-height:1.15">{t(lang,'Vi hjelper deg<br>gjerne på vei.','We are happy<br>to help you plan.')}</h2></div><div><p>{t(lang,'Lurer du på noe før bestilling eller ankomst? Ta kontakt med Eva eller Dan. Har du allerede bestilt, kan du også svare oss i bestillingskanalen.','Have a question before booking or arriving? Contact Eva or Dan. If you have already booked, you can also reply through your booking channel.')}</p><div class="contact-block"><div><small>Eva</small><a href="tel:+4795403024">+47 954 03 024</a></div><div><small>Dan</small><a href="tel:+4791541662">+47 915 41 662</a></div></div></div></div></section>'''+closing(lang)
 layout(lang,'location',content,t(lang,'Beliggenhet og kontakt','Location and contact'),t(lang,'Finn veien til Brennvik Panorama, Brennvikveien 37 i Hamarøy. Kart, veibeskrivelse og kontakt med vertene.','Find Brennvik Panorama at Brennvikveien 37 in Hamarøy. Maps, directions and contact details for your hosts.'))

def booking(lang):
 content=head(lang,'booking',t(lang,'Finn noen dager<br>som er bare deres.','Find a few days<br>to call your own.'),t(lang,'Velg datoer og antall gjester for å se tilgjengelighet og pris. Bestillingen fullføres på engelsk hos Lodgify.','Choose your dates and number of guests to see availability and pricing. Your booking is handled by Lodgify.'))
 widget=BOOKING.get('embed_'+lang,'')
 if not widget: raise ValueError('A verified booking embed is required before generating the site')
 content+=f'''<section class="section-small" style="padding-top:0"><div class="wrap booking-layout"><aside class="booking-info">{pic(lang,'exterior',eager=True)}<h2>Brennvik Panorama</h2><p>Hamarøy · {t(lang,'Nord-Norge','Northern Norway')}</p><ul><li>{t(lang,'Hele hytta · 49 m²','Entire cabin · 49 m²')}</li><li>{t(lang,'To soverom','Two bedrooms')}</li><li>{t(lang,'Innsjekk fra kl. 15.00','Check-in from 15:00')}</li><li>{t(lang,'Utsjekk innen kl. 11.00','Checkout by 11:00')}</li></ul><p>{t(lang,'Du ser gjeldende pris, tillegg og vilkår før du bekrefter.','You will see the current price, any extras and the terms before you confirm.')}</p>{link(lang,'cabin',t(lang,'Les om hytta og drikkevannet','Read about the cabin and drinking water'))}</aside><div><div class="booking-panel"><h2>{t(lang,'Ditt opphold','Your stay')}</h2><p>{t(lang,'Velg datoene du ønsker.','Select your preferred dates.')}</p><div class="booking-embed">{widget}</div><div class="booking-direct"><a class="text-link" href="{esc(CHECKOUT)}" target="_blank" rel="noopener">{t(lang,'Åpne bestillingen i eget vindu','Open booking in a new window')} ↗</a></div></div><p class="booking-help">{t(lang,'Hvis bestillingsfeltet ikke vises, åpne bestillingen i eget vindu. Har du spørsmål, ring','If the booking form does not appear, open booking in a new window. For questions, call')} <a href="tel:+4791541662">Dan · +47 915 41 662</a>.</p></div></div></section>'''
 content+=f'''<section class="section-small"><div class="wrap practical"><div><h2 class="serif" style="font-size:35px">{t(lang,'Før du bekrefter','Before you confirm')}</h2></div><div>{faq(t(lang,'Pris og avbestilling','Price and cancellation'),t(lang,'Endelig pris og avbestillingsvilkår følger datoene og alternativet du velger i Lodgify. Les oppsummeringen før du bekrefter bestillingen.','The final price and cancellation terms depend on your dates and the option you select in Lodgify. Read the summary before confirming your booking.'))}{faq(t(lang,'Spørsmål om oppholdet?','Questions about your stay?'),t(lang,'Ta gjerne kontakt med Eva eller Dan. Du finner flere detaljer om hytta og praktisk informasjon i gjesteguiden.','Contact Eva or Dan. Our guest guide contains more details about the cabin and practical information.'))}</div></div></section>'''
 layout(lang,'booking',content,t(lang,'Ledige datoer og bestilling','Availability and booking'),t(lang,'Se ledige datoer, pris og vilkår for Brennvik Panorama. Bestill oppholdet gjennom Lodgify.','Check availability, pricing and terms for Brennvik Panorama. Book your stay through Lodgify.'))

def privacy(lang):
 content=head(lang,'privacy',t(lang,'Personvern','Privacy'),t(lang,'Om denne nettsiden og bestillingen din.','About this website and your booking.'))
 content+=f'''<section class="section-small"><div class="wrap legal"><h2>{t(lang,'Nettsiden','This website')}</h2><p>{t(lang,'Nettsiden presenterer Brennvik Panorama, som drives av Skoglund Heim AS. Vi har ikke lagt inn analyseverktøy, markedsføringspiksler eller kontaktskjema på disse sidene. Teknisk logging kan forekomme hos leverandøren som drifter nettsiden.','This website presents Brennvik Panorama, operated by Skoglund Heim AS. We have not added analytics tools, advertising pixels or contact forms to these pages. Technical logging may be performed by the hosting provider.')}</p><h2>{t(lang,'Bestilling via Lodgify','Booking through Lodgify')}</h2><p>{t(lang,'På bestillingssiden lastes innhold fra Lodgify. Opplysninger du gir ved bestilling, og eventuell betaling, behandles gjennom bestillingsløsningen. Se personverninformasjonen og vilkårene som vises der.','The booking page loads content from Lodgify. Details you provide when booking, and any payment, are processed through the booking service. Refer to the privacy information and terms shown there.')}</p><p><a href="https://www.lodgify.com/privacy/" target="_blank" rel="noopener">{t(lang,'Lodgifys personverninformasjon','Lodgify privacy information')} ↗</a></p><h2>{t(lang,'Eksterne lenker','External links')}</h2><p>{t(lang,'Kart, gjesteguide og lenker til lokale opplevelser åpnes hos andre tjenester. Der gjelder tjenestens egne vilkår og personverninformasjon.','Maps, the guest guide and links to local experiences open on other services, where the service’s own terms and privacy information apply.')}</p><h2>{t(lang,'Kontakt','Contact')}</h2><p>{t(lang,'Har du spørsmål om opplysninger knyttet til oppholdet ditt, kontakt Dan på','For questions about information relating to your stay, contact Dan on')} <a href="tel:+4791541662">+47 915 41 662</a>.</p></div></section>'''
 layout(lang,'privacy',content,t(lang,'Personvern','Privacy'),t(lang,'Personverninformasjon for Brennvik Panorama og bestilling gjennom Lodgify.','Privacy information for Brennvik Panorama and booking through Lodgify.'))

for lang in ['no','en']:
 for page in [home,cabin,gallery,explore,location,booking,privacy]: page(lang)
